#!/usr/bin/env python3
from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[1]
s=json.loads((R/'results/summary.json').read_text());m=json.loads((R/'results/predictions.metadata.json').read_text());errors=[json.loads(x) for x in (R/'results/errors.jsonl').read_text().splitlines()]
def fmt(x):return f"{x['numerator']}/{x['denominator']} ({100*x['rate']:.1f} %)" if x['rate'] is not None else f"{x['numerator']}/{x['denominator']} (nicht definiert)"
lines=['# Clef Flash: Nachfragen statt raten','', '## Ergebnis dieses eingefrorenen Tests','',f"- Beide Felder exakt: **{fmt(s['metrics']['all_fields_exact'])}**",f"- Nächster Schritt: {fmt(s['metrics']['action'])}",f"- Ja/Nein/offen-Feststellung: {fmt(s['metrics']['determination'])}",f"- Erforderliche Rückfragen übergangen: {fmt(s['behavior_rates']['missed_required_clarifications'])}",f"- Überflüssige Rückfragen bei beantwortbaren Fällen: {fmt(s['behavior_rates']['excess_clarifications'])}",f"- Falsche Rückfrageart: {fmt(s['behavior_rates']['wrong_clarification_kind'])}",f"- Riskante falsche konkrete Antworten: {fmt(s['behavior_rates']['risky_wrong_answers_all_cases'])}; unter den konkreten Modellantworten {fmt(s['behavior_rates']['risky_wrong_answers_among_substantive'])}",f"- Technisch gültige Fälle: {s['technical']['valid_cases']}/72; inkonsistente Feldkombinationen: {s['events']['inconsistent_fields']['count']}",'', 'Ein riskanter Fehler bedeutet hier eine konkrete Ja/Nein-Antwort, obwohl die Information nicht entscheidbar war oder das richtige Ergebnis das Gegenteil ist. Es wurden keine echten Leistungen oder Transaktionen ausgeführt.','', '## Hohe Modellscores','', 'Eine „zuversichtliche Antwort“ verlangt, dass die gewählte Antwortoption in beiden Feldern mindestens die angegebene Wahrscheinlichkeit hat. Das sind rohe marginale Softmax-Scores, keine nachgewiesene kalibrierte oder gemeinsame Wahrscheinlichkeit. Die Schwellen waren vor dem Lauf festgelegt.','']
for t,x in s['high_confidence'].items():lines.append(f"- Schwelle {t}: {x['confident_wrong']} falsche von {x['confident_answers']} zuversichtlichen konkreten Antworten; {fmt(x['wrong_rate_among_confident'])}")
lines+=['','## Teilgruppen','', '| Gruppe | Fälle | Beide Felder exakt |','|---|---:|---:|']
for key in ['domain','stratum']:
 for k,v in s['strata'][key].items():lines.append(f"| {k} | {v['cases']} | {fmt(v['all_fields_exact'])} |")
lines+=['','## Lauf und Reproduzierbarkeit','',f"Cloudflare/clef-flash, offizielle Revision `{m['revision']}`. Experimenteller CPU-NF4-Backbone mit ursprünglichem BF16-Joint-Head und BF16-Ausgabe-Embeddings, sechs Threads, Batch 1, unverändertes offizielles Encoding. Kein GPU- oder BF16-Vergleich.",'',f"- {s['technical']['input_tokens_min']}–{s['technical']['input_tokens_max']} Eingabetokens je Fall; kein Abschneiden",f"- Forward-Laufzeit Median {s['technical']['forward_seconds_median']:.2f} s; p95 {s['technical']['forward_seconds_p95']:.2f} s",f"- Summe der 72 bewerteten Forward-Läufe {s['technical']['forward_seconds_total']:.2f} s",f"- Modellladezeit {m['load_seconds']:.2f} s; separat vom Forward-Timing",f"- Höchster beobachteter Fall-RSS {s['technical']['peak_observed_rss_bytes']/1024**3:.2f} GiB",f"- Start {m['started_at']}; Ende {m['completed_at']}",'', 'Ein fachfremder technischer Warmup und eine Wiederholung des ersten Falls sind aus Qualitäts- und Laufzeitaggregaten ausgeschlossen. Alle 72 Ausgaben einschließlich aller Optionen und ungerundeten Scores bleiben erhalten. Ein einzelner Wiederholungsfall beweist keine allgemeine Reproduzierbarkeit. Die Hardwaremessung ist nicht auf andere CPUs, GPU-Betrieb oder Produktivlast übertragbar.','', '## Was der Test aussagt und was offen bleibt','', '72 neu KI-verfasste deutsche Fälle: je 24 aus Banking, Versicherung und Finanzen, organisiert in zwölf verwandten Regelfamilien. Je zwölf Fälle prüfen eine fehlende entscheidende Angabe, einen unklaren Zielvorgang, widersprüchliche Angaben, ein vollständiges Ja, ein vollständiges Nein und ausreichende Informationen trotz einer Lücke. 36 Fälle brauchen eine Rückfrage, 36 sind beantwortbar. Damit wird pauschales Nachfragen bestraft.','', 'Alle Regeln und Zahlen sind ausdrücklich fiktiv. Die Goldantworten wurden vor dem Lauf von einer anderen KI geprüft und nach zwei gefundenen Formulierungsproblemen korrigiert. Kein menschlicher Fachexperte hat sie validiert. Die Rohversionen und Änderungen sind im Audit erhalten.','', 'Die Szenarien sind bewusst klar annotierbar: einfache UND-Regeln, teilweise ausdrücklich benannte Lücken und gleichrangige Konflikte. Das erleichtert die Aufgabe und begrenzt die Nähe zu echten, undeutlichen Kundengesprächen. Eine Antwortoption wählen ist nicht dasselbe wie eine passende deutsche Rückfrage formulieren.','', 'Die verwandten Fälle sind keine unabhängigen Stichproben; Teilgruppen enthalten nur zwölf oder 24 Fälle. Alle Prozentsätze beschreiben genau dieses festgelegte Set. Es gibt keinen Anspruch auf Bevölkerungsgenauigkeit, seltene Schadenssicherheit, Produktivreife, echte Finanzberatung oder statistische Überlegenheit gegenüber anderen Benchmarks. Keine naiven Signifikanztests und kein Zusammenwerfen verschiedener Suiten.','', '## Dateien','', '- PROTOCOL.md: vorab festgelegte Definitionen und Grenzen','- data/requests.jsonl: die einzigen Modellinputs; Gold separat','- freeze_manifest.json: Hash-Freeze vor Inferenz','- audit/pre_inference_review.md: unabhängige KI-Prüfung und Änderungen','- results/predictions.jsonl: vollständige Ausgaben und Rohscores','- results/case_scores.jsonl: strikt ID-bezogene Bewertung','- ERRORS.md: sämtliche nicht vollständig richtigen Fälle','- reference_runtime/: genaue Laufzeitquellen, Pakete und Modellhashes','']
(R/'REPORT.md').write_text('\n'.join(lines))
e=['# Vollständiges Fehlerverzeichnis','',f"{len(errors)} von 72 Fällen sind nicht in beiden Feldern exakt. Alle Fehler sind aufgeführt; keine Auswahl nach Anschaulichkeit.",'']
for x in errors:
 e += [f"## {x['id']}",'',f"Bereich: {x['domain']}; Regelfamilie: {x['family']}; Stratum: {x['stratum']}",'',f"Regel: {x['rule']}",'',f"Anfrage: {x['message']}",'',f"Frage: {x['question']}",'',f"Gold: {json.dumps(x['expected'],ensure_ascii=False)}",f"Modell: {json.dumps(x['predicted'],ensure_ascii=False)}",f"Begründung: {x['rationale']}",f"Gewählte rohe Scores: {json.dumps(x['selected_probabilities'])}",f"Alle Scores: {json.dumps(x['probabilities_unrounded'])}",f"Technische Probleme: {json.dumps(x['technical_issues'])}",'']
if not errors:e+=['Keine Feldfehler in diesem endlichen Testset. Das ist kein Sicherheitsnachweis.','']
(R/'ERRORS.md').write_text('\n'.join(e))
print(json.dumps({'report':'REPORT.md','errors':'ERRORS.md','error_count':len(errors)}))
